package com.primehr.learningdevelopment.evaluation.api;
import com.primehr.learningdevelopment.evaluation.api.LdEvaluationDtos.*;import com.primehr.learningdevelopment.evaluation.application.LdEvaluationService;import com.primehr.security.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.List;
@RestController @RequestMapping("/api/primehr/v1/learning-development/evaluation")
public class LdEvaluationController {private final LdEvaluationService service;private final LdEvaluationPermissionGuard permission;private final LdReportingPermissionGuard reporting;private final AgencyScopeResolver agencies;public LdEvaluationController(LdEvaluationService service,LdEvaluationPermissionGuard permission,LdReportingPermissionGuard reporting,AgencyScopeResolver agencies){this.service=service;this.permission=permission;this.reporting=reporting;this.agencies=agencies;}
 @GetMapping("/tasks")public List<TaskResponse>tasks(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token){return service.tasks(agency(a),actor(a),permission.require(LdEvaluationPermissionGuard.EVALUATION,PrimeHrAction.ACCESS,token));}
 @GetMapping("/tasks/mine")public List<TaskResponse>mine(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token){permission.require(LdEvaluationPermissionGuard.EVALUATION,PrimeHrAction.ACCESS,token);return service.mine(agency(a),actor(a));}
 @GetMapping("/tasks/assigned")public List<TaskResponse>assigned(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token){permission.require(LdEvaluationPermissionGuard.EVALUATION,PrimeHrAction.ACCESS,token);return service.assigned(agency(a),actor(a));}
 @PostMapping("/completion-cases/{id}/initialize")@ResponseStatus(HttpStatus.CREATED)public List<TaskResponse>initialize(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody InitializeInput input){return service.initialize(agency(a),id,input,actor(a),permission.require(LdEvaluationPermissionGuard.EVALUATION,PrimeHrAction.ADD,token),correlation);}
 @PostMapping("/tasks/{id}/results")@ResponseStatus(HttpStatus.CREATED)public ResultResponse submit(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody ResultInput input){permission.require(LdEvaluationPermissionGuard.EVALUATION,PrimeHrAction.SUBMIT,token);return service.submitResult(agency(a),id,input,actor(a),correlation);}
 @PostMapping("/tasks/{id}/results/{resultId}/decision")public TaskResponse decide(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@PathVariable String resultId,@Valid @RequestBody DecisionInput input){return service.decideResult(agency(a),id,resultId,input,actor(a),permission.require(LdEvaluationPermissionGuard.EVALUATION,PrimeHrAction.APPROVE,token),correlation);}
 @GetMapping("/action-plans")public List<LapResponse>plans(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token){return service.actionPlans(agency(a),actor(a),permission.require(LdEvaluationPermissionGuard.EVALUATION,PrimeHrAction.ACCESS,token));}
 @GetMapping("/action-plans/mine")public List<LapResponse>minePlans(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token){permission.require(LdEvaluationPermissionGuard.EVALUATION,PrimeHrAction.ACCESS,token);return service.myActionPlans(agency(a),actor(a));}
 @GetMapping("/action-plans/assigned")public List<LapResponse>assignedPlans(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token){permission.require(LdEvaluationPermissionGuard.EVALUATION,PrimeHrAction.ACCESS,token);return service.assignedActionPlans(agency(a),actor(a));}
 @PostMapping("/completion-cases/{id}/action-plan")@ResponseStatus(HttpStatus.CREATED)public LapResponse createPlan(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody LapInput input){return service.createActionPlan(agency(a),id,input,actor(a),permission.require(LdEvaluationPermissionGuard.EVALUATION,PrimeHrAction.ADD,token),correlation);}
 @PutMapping("/action-plans/{id}")public LapResponse updatePlan(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody LapUpdate input){return service.updateActionPlan(agency(a),id,input,actor(a),permission.require(LdEvaluationPermissionGuard.EVALUATION,PrimeHrAction.EDIT,token),correlation);}
 @PostMapping("/action-plans/{id}/submit")public LapResponse submitPlan(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody Transition input){permission.require(LdEvaluationPermissionGuard.EVALUATION,PrimeHrAction.SUBMIT,token);return service.submitActionPlan(agency(a),id,input,actor(a),correlation);}
 @PostMapping("/action-plans/{id}/follow-up")public LapResponse followUp(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id,@Valid @RequestBody FollowUpInput input){return service.followUp(agency(a),id,input,actor(a),permission.require(LdEvaluationPermissionGuard.EVALUATION,PrimeHrAction.APPROVE,token),correlation);}
 @GetMapping("/effectiveness")public EffectivenessResponse effectiveness(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation){reporting.requireAnalytics(token);return service.effectiveness(agency(a),actor(a),correlation);}
 @GetMapping("/completion-cases/{id}/hrm-review-packet")public HrmReviewPacket reviewPacket(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String token,@RequestHeader(value="X-Correlation-Id",required=false)String correlation,@PathVariable String id){return service.hrmReviewPacket(agency(a),id,actor(a),permission.require(LdEvaluationPermissionGuard.EVALUATION,PrimeHrAction.ACCESS,token),correlation);}
 private String agency(Authentication a){return agencies.resolveAgencyId(a);}private static String actor(Authentication a){if(a==null||a.getName()==null||a.getName().isBlank())throw new org.springframework.security.access.AccessDeniedException("Authenticated identity is required");return a.getName();}}
